import React, { useState, useEffect, useRef, memo } from 'react';

// Constants
const MEDIA_TYPES = {
  VIDEO: 'video',
  GIF: 'gif',
  IMAGE: 'image',
  EMBED: 'embed'
};

const VIDEO_EXTENSIONS = ['.mp4', '.mov', '.webm'];
const IMAGE_EXTENSIONS = ['.jpeg', '.jpg', '.png', '.webp'];
const GIF_EXTENSIONS = ['.gif'];

const EMBED_INDICATORS = ['ifr', 'embed']; // URLs containing these are embeds

export const BUTTON_CONFIG = [
    {
    className: 'close-icon',
    icon: 'fas fa-times',
    ariaLabel: 'Close fullscreen view',
    handler: 'close'
  },
  { 
    className: 'like-icon', 
    icon: 'fas fa-heart',
    ariaLabel: 'Add to likes',
    handler: 'like'
  },
  { 
    className: 'postlink-icon', 
    icon: 'fas fa-link',
    ariaLabel: 'Open post link',
    handler: 'link'
  },
  { 
    className: 'remove-icon', 
    icon: 'fas fa-trash',
    ariaLabel: 'Remove media',
    handler: 'remove'
  },
  { 
    className: 'number-icon', 
    icon: 'fas fa-film',
    ariaLabel: 'Number of video links',
    handler: 'number',
    isInfoOnly: true,
    condition: (postLink, videoLinks) => videoLinks.length > 1
  }
];

// Utility functions
const getMediaType = (url) => {
  const lower = url.toLowerCase();
  
  // Check for embed URLs first (they don't have file extensions)
  if (EMBED_INDICATORS.some(indicator => lower.includes(`/${indicator}`))) {
    return MEDIA_TYPES.EMBED;
  }
  
  if (VIDEO_EXTENSIONS.some(ext => lower.endsWith(ext))) return MEDIA_TYPES.VIDEO;
  if (GIF_EXTENSIONS.some(ext => lower.endsWith(ext))) return MEDIA_TYPES.GIF;
  if (IMAGE_EXTENSIONS.some(ext => lower.endsWith(ext))) return MEDIA_TYPES.IMAGE;
  
  // If no extension found and not an embed, default to image
  return MEDIA_TYPES.IMAGE;
};

// Optimized MediaItem with lazy loading
export const MediaItem = React.memo(({ 
    media, 
    index, 
    fullscreenIndex, 
    isFullscreen: isFullscreenProp, 
    isLoaded, 
    globalVolume, 
    onMediaClick, 
    onImageError,
    onVideoError, 
    onIconClick,
    onClose,
    onRemove,
    onLike,
    isLiked,
    mediaRef,
    masonryRef,
}) => {
    const { postLink, videoLinks = []} = media || {};
    const [isMediaLoaded, setIsMediaLoaded] = useState(false);
    const [isLikedLocal, setIsLikedLocal] = useState(isLiked || false);
    const wrapperRef = useRef(null);
    
    if (!media || videoLinks.length === 0 || !videoLinks[0]) return null;

    const handleMediaLoad = () => {
        setIsMediaLoaded(true);
        if (wrapperRef.current) {
            wrapperRef.current.classList.add('loaded');
        }
        // ← Throttle masonry layout with requestAnimationFrame to avoid excessive recalculations
        if (masonryRef?.current?.layout) {
            requestAnimationFrame(() => {
                if (masonryRef?.current?.layout) {
                    masonryRef.current.layout();
                }
            });
        }
    }


    const handleMediaError = (e, postLink, type) => {
        console.error(`${type} failed to load:`, {
            url: e.target?.src || e.target?.currentSrc,
            postLink
        });

        // Hide the broken element immediately
        if (e.target) {
            e.target.style.display = 'none';
        }

        // Hide the placeholder by marking as loaded
        setIsMediaLoaded(true);

        if (type === 'Image') {
            onImageError(e, postLink);
        } else {
            onVideoError(e, postLink);
        }
    };

    // Use explicit prop if provided, otherwise fall back to index comparison
    const isFullscreen = isFullscreenProp !== undefined ? isFullscreenProp : (fullscreenIndex === index);

    const renderMediaElement = (videoLink, postLink, globalVolume, isFullscreen, ref) => {
        const mediaType = getMediaType(videoLink);
        const isVideo = mediaType === MEDIA_TYPES.VIDEO;
        const isEmbed = mediaType === MEDIA_TYPES.EMBED;

        if (isEmbed) {
            return (
                <iframe
                    ref={ref}
                    key={`${postLink}-embed`}
                    title={`Embedded media from ${postLink}`}
                    src={videoLink}
                    frameBorder="0"
                    allowFullScreen
                    onLoad={() => handleMediaLoad()}
                    onError={(e) => handleMediaError(e, postLink, 'Embed')}
                    className="media-embed"
                />
            );
        }

        if (isVideo) {
            return (
                <>
                    <video
                        ref={ref}
                        key={`${postLink}-video`}
                        src={ videoLink}
                        controls={isFullscreen} // Show controls only in fullscreen
                        muted={!isFullscreen}
                        loop
                        autoPlay={isFullscreen}
                        fetchpriority={isFullscreen ? "high" : "auto"}
                        preload={isFullscreen ? "high" : "metadata"}
                        loading="lazy"
                        onLoadedData={(e) => {
                            e.target.volume = globalVolume;
                            handleMediaLoad();
                        }}
                        onPlay={(e) => { e.target.volume = globalVolume; }}
                        onError={(e) => handleMediaError(e, postLink, 'Video')}
                        className="media-video"
                        style={{ opacity: isMediaLoaded ? 1 : 0, transition: 'opacity 0.5s ease-in' }}
                    />
                    {!isMediaLoaded && (
                        <div className="image-loading-placeholder">
                            <div className="loading-spinner"></div>
                        </div>
                    )}
                </>
            );
        }

        return (
            <>
                <img
                    ref={ref}
                    key={`${postLink}-img-${videoLink}`}
                    src={videoLink}
                    alt="Media content"
                    loading="lazy"
                    fetchpriority={isFullscreen ? "high" : "low"}
                    decoding="async"
                    onLoad={() => {
                        handleMediaLoad();
                    }}
                    onError={(e) => handleMediaError(e, postLink, 'Image')}
                    className="media-image"
                    // fade in when loaded
                    style={{ opacity: isMediaLoaded ? 1 : 0, transition: 'opacity 0.5s ease-in' }}
                    />
                {!isMediaLoaded && (
                    <div className="image-loading-placeholder">
                        <div className="loading-spinner"></div>
                    </div>
                )}
            </>
        );
    };

    const handleLikeClick = (e) => {
        e.stopPropagation();
        setIsLikedLocal(!isLikedLocal);
        onLike(postLink, !isLikedLocal);
    };

    const handleIconButtonClick = (handler, e) => {
        e.stopPropagation();
        switch (handler) {
            case 'like':
                handleLikeClick(e);
                break;
            case 'link':
                onIconClick(postLink);
                break;
            case 'remove':
                onRemove(postLink);
                break;
            case 'close':
                onClose(postLink);
                break;
            default:
                break;
        }
    };

    return (
        <div
            ref={wrapperRef}
            className={`media-wrapper masonry-item ${isMediaLoaded ? 'loaded' : ''} ${isFullscreen ? 'fullscreen' : ''}`}
            onClick={() => onMediaClick(index)}
            data-index={index}
        >
            {isFullscreen && videoLinks.length > 1 ? (
                videoLinks.map((videoLink, idx) => 
                    <React.Fragment key={`${postLink}-${idx}`}>
                        {renderMediaElement(videoLink, postLink, globalVolume, isFullscreen, idx === 0 ? mediaRef : null)}
                    </React.Fragment>
                )
            ) : (
                renderMediaElement(videoLinks[0], postLink, globalVolume, isFullscreen, mediaRef)
            )}
            
            {!isFullscreen && (
                <>
                    <div className="icon-container">
                        {BUTTON_CONFIG.map((btn) => {
                            const shouldRender = !btn.condition || (postLink && btn.condition(postLink, videoLinks));
                            if (!shouldRender) return null;

                            const isLikeButton = btn.handler === 'like';
                            
                            // Handle info-only buttons (like number-icon)
                            if (btn.isInfoOnly) {
                                return (
                                    <button
                                        key={btn.handler}
                                        className={btn.className}
                                        aria-label={btn.ariaLabel}
                                        disabled
                                    >
                                        <i className={btn.icon}></i>
                                        <span className="button-count">{videoLinks.length}</span>
                                    </button>
                                );
                            }
                            
                            return (
                                <button
                                    key={btn.handler}
                                    className={`${btn.className} ${isLikeButton && isLikedLocal ? 'liked' : ''}`}
                                    onClick={(e) => handleIconButtonClick(btn.handler, e)}
                                    aria-label={btn.ariaLabel}
                                >
                                    <i className={`${btn.icon} ${isLikeButton && isLikedLocal ? 'filled' : ''}`}></i>
                                </button>
                            );
                        })}
                    </div>
                </>
            )}
        </div>
    );
}, (prevProps, nextProps) => {
    return (
        prevProps.index === nextProps.index &&
        prevProps.fullscreenIndex === nextProps.fullscreenIndex &&
        prevProps.isFullscreen === nextProps.isFullscreen &&
        prevProps.isLoaded === nextProps.isLoaded &&
        prevProps.globalVolume === nextProps.globalVolume
    );
});

// TagsPanel component - displays categorized tags
export const TagsPanel = ({ 
    tags, 
    tagFilter, 
    onTagClick, 
    onAddTagToFilter, 
    onAddTagToBlacklist,
    onFilterByDomain,
    onAddTagToScrapelist,
    isMinimized,
    onToggleMinimized,
    domainFilter,
    fullscreenMedia
}) => {
    const [isCollapsed, setIsCollapsed] = useState(isMinimized);

    useEffect(() => {
        setIsCollapsed(isMinimized);
    }, [isMinimized]);

    const handleToggleCollapse = () => {
        setIsCollapsed(!isCollapsed);
        onToggleMinimized();
    };

    if (!tags) return null;

    const categorizedTags = Array.isArray(tags) ? { general: tags } : tags;

    // Determine copyright label based on domain
    const isRedGifs = categorizedTags?.domain?.includes('RedGifs');
    const copyrightLabel = isRedGifs ? 'Niches' : 'Copyright';

    
    const categories = [
        { key: 'domain', label: 'Domain' },
        { key: 'author', label: 'Artists' },
        { key: 'copyright', label: copyrightLabel },
        { key: 'character', label: 'Characters' },
        { key: 'general', label: 'General' }
    ];
    
    return (
        <div className={`tags-panel ${isMinimized ? 'minimized' : ''}`}>
            <div className="tags-header">
                <span className="tags-header-title">Tags</span>
                <div className="tags-header-controls">
                    <button 
                        className="tags-minimize-button"
                        onClick={handleToggleCollapse}
                        title={isCollapsed ? "Expand tags" : "Minimize tags"}
                    >
                        <i className={`fas ${isCollapsed ? 'fa-chevron-right' : 'fa-chevron-left'}`}></i>
                    </button>
                </div>
            </div>
            
            {!isCollapsed && (
                <div className="tags-content">
                    {categories.map(category => {
                        let categoryTags = categorizedTags[category.key];
                        // Convert string to array, or ensure it's an array
                        if (typeof categoryTags === 'string') {
                            categoryTags = [categoryTags];
                        }
                        if (!categoryTags || categoryTags.length === 0) return null;
                        
                        return (
                            <div key={category.key} className="tag-category">
                                <h3 className="tag-category-header">{category.label}</h3>
                                <div className="tags-list">
                                    {categoryTags.map((tag, idx) => {
                                        const mediaDomain = fullscreenMedia?.tags?.domain?.[0];
                                        return (
                                        <div 
                                            key={`${category.key}-${idx}`}
                                            className="tag-container"
                                        >
                                            <span 
                                                className={`tag tag-${category.key} ${tagFilter.includes(tag) ? 'active' : ''}`}
                                                onClick={(e) => category.key === 'domain' && onFilterByDomain ? onFilterByDomain(tag, e) : onTagClick(tag, e, mediaDomain || domainFilter)}
                                            >
                                                {tag}
                                            </span>
                                            {category.key !== 'domain' && (
                                                <div className="tag-actions">
                                                    <button 
                                                        className="tag-action tag-action-plus" 
                                                        onClick={(e) => onAddTagToFilter(tag, e)}
                                                        title="Filter by this tag"
                                                    >
                                                        <i className="fas fa-plus"></i>
                                                    </button>
                                                    <button 
                                                        className="tag-action tag-action-minus" 
                                                        onClick={(e) => onAddTagToBlacklist(tag, e)}
                                                        title="Add to blacklist"
                                                    >
                                                        <i className="fas fa-minus"></i>
                                                    </button>
                                                    {onAddTagToScrapelist && (
                                                        <button 
                                                            className="tag-action tag-action-scrapelist" 
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                onAddTagToScrapelist(tag);
                                                            }}
                                                            title="Add tag to scrapelist"
                                                        >
                                                            <i className="fas fa-list"></i>
                                                        </button>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    );
                                    })}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
};

// NotificationContainer component - displays notifications
export const NotificationContainer = ({ notifications, onRemoveNotification }) => (
    <div className="notifications-container">
        {notifications.map((notification) => (
            <div 
                key={notification.id} 
                className={`notification ${notification.type}`}
                style={{ top: `${20 + (Array.from(notifications).findIndex(n => n.id === notification.id) * 70)}px` }}
            >
                <button
                    className="notification-close-btn"
                    onClick={() => onRemoveNotification(notification.id)}
                    aria-label="Close notification"
                >
                    <i className="fas fa-times"></i>
                </button>
                {notification.type === 'progress' ? (
                    <>
                        {typeof notification.progress === 'number' && !notification.isComplete ? (
                            <div className="notification-progress-wrapper">
                                <p className="notification-message">{notification.message}</p>
                                <div className="notification-progress-circle">
                                    <svg className="progress-ring" viewBox="0 0 100 100">
                                        <circle className="progress-ring-bg" cx="50" cy="50" r="45" />
                                        <circle 
                                            className="progress-ring-fill" 
                                            cx="50" 
                                            cy="50" 
                                            r="45"
                                            style={{
                                                strokeDashoffset: 282.7 - (282.7 * notification.progress) / 100
                                            }}
                                        />
                                    </svg>
                                    <span className="notification-progress-text">{notification.progress}%</span>
                                </div>
                            </div>
                        ) : null}
                        {notification.isComplete ? (
                            <p className="notification-message notification-completed">
                                Completed!
                            </p>
                        ) : null}
                        {!notification.isComplete && notification.progress === undefined ? (
                            <div className="notification-loading">
                                <div className="notification-spinner"></div>
                            </div>
                        ) : null}
                    </>
                ) : (
                    <>
                        <p className="notification-message">{notification.message}</p>
                        <div className="notification-progress" />
                    </>
                )}
            </div>
        ))}
    </div>
);

// ScraplistItem - simple memoized item with no virtualizer overhead
const ScraplistItem = memo(({ url, index, onRemove }) => (
    <li className="scrapelist-item">
        <span className="scrapelist-url" title={url}>{url}</span>
        <button 
            className="scrapelist-delete-btn"
            onClick={() => onRemove(index)}
            title="Remove from scrapelist"
            aria-label={`Remove ${url}`}
        >
            <i className="fas fa-times"></i>
        </button>
    </li>
));

ScraplistItem.displayName = 'ScraplistItem';

// Reusable hook for click-outside detection
const useClickOutsideModal = (isOpen, refElement, onClose) => {
    useEffect(() => {
        if (!isOpen) return;

        const handleClickOutside = (event) => {
            if (refElement?.current && !refElement.current.contains(event.target)) {
                onClose();
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [isOpen, refElement, onClose]);
};

// SettingsDialog component - settings modal
const SettingsDialogComponent = ({ 
    showSettings,
    showDefaultLinks,
    filter,
    scrollSpeed,
    globalVolume,
    tagBlacklist,
    onClose,
    onShowDefaultLinksChange,
    onFilterChange,
    onScrollSpeedChange,
    onVolumeChange,
    onAddTag,
    onRemoveTag,
    onDeleteBlacklisted,
    updateSliderFill,
    updateVolumeSliderFill
}) => {
    const [newTag, setNewTag] = useState('');
    const settingsDialogRef = useRef(null);

    useClickOutsideModal(showSettings, settingsDialogRef, onClose);

    const handleAddTagClick = () => {
        if (newTag.trim()) {
            onAddTag(newTag);
            setNewTag('');
        }
    };

    if (!showSettings) return null;

    const tagArray = Array.isArray(tagBlacklist) ? tagBlacklist : [];

    return (
        <div className="settings-dialog-overlay">
            <div className="settings-modal" ref={settingsDialogRef}>
                <div className="settings-modal-header">
                    <h2>Gallery Settings</h2>
                    <button 
                        className="settings-close-btn"
                        onClick={onClose}
                        aria-label="Close modal"
                    >
                        <i className="fas fa-times"></i>
                    </button>
                </div>

                <div className="settings-modal-content">
                    {/* Include Demo Content Toggle */}
                    <div className="settings-section">
                        <label className="settings-section-title">Include Demo Content</label>
                        <div className="settings-toggle-buttons">
                            <button 
                                className={`settings-toggle-btn ${showDefaultLinks ? 'active' : ''}`}
                                onClick={() => onShowDefaultLinksChange(true)}
                            >
                                Show
                            </button>
                            <button 
                                className={`settings-toggle-btn ${!showDefaultLinks ? 'active' : ''}`}
                                onClick={() => onShowDefaultLinksChange(false)}
                            >
                                Hide
                            </button>
                        </div>
                    </div>

                    {/* Auto-Scroll Speed */}
                    <div className="settings-section">
                        <label htmlFor="scroll-speed" className="settings-section-title">
                            Auto-Scroll Speed: {scrollSpeed}px/tick
                        </label>
                        <input
                            id="scroll-speed"
                            type="range"
                            min="1"
                            max="10"
                            value={scrollSpeed}
                            onChange={(e) => {
                                const newSpeed = parseInt(e.target.value, 10);
                                onScrollSpeedChange(newSpeed);
                                updateSliderFill(newSpeed);
                            }}
                            className="settings-slider"
                        />
                        <div className="settings-slider-labels">
                            <span>Slow</span>
                            <span>Fast</span>
                        </div>
                    </div>

                    {/* Volume Control */}
                    <div className="settings-section">
                        <label htmlFor="volume-control" className="settings-section-title">
                            Volume: {Math.round(globalVolume * 100)}%
                        </label>
                        <input
                            id="volume-control"
                            type="range"
                            min="0"
                            max="1"
                            step="0.01"
                            value={globalVolume}
                            onChange={(e) => {
                                const newVolume = parseFloat(e.target.value);
                                onVolumeChange(newVolume);
                                updateVolumeSliderFill(newVolume);
                            }}
                            className="settings-slider"
                        />
                    </div>

                    {/* Tag Blacklist */}
                    <div className="settings-section">
                        <label className="settings-section-title">Tag Blacklist</label>
                        
                        {/* Add Tag Controls */}
                        <div className="blacklist-add-controls">
                            <input
                                type="text"
                                placeholder="Enter tag to blacklist"
                                value={newTag}
                                onChange={(e) => setNewTag(e.target.value)}
                                onKeyPress={(e) => e.key === 'Enter' && handleAddTagClick()}
                                className="blacklist-input"
                            />
                            <button 
                                className="blacklist-add-btn"
                                onClick={handleAddTagClick}
                            >
                                <i className="fas fa-plus"></i>
                            </button>
                        </div>

                        {/* Tag List */}
                        {tagArray.length > 0 && (
                            <ul className="blacklist-tags">
                                {tagArray.map((tag, index) => (
                                    <li key={index} className="blacklist-tag-item">
                                        <span className="blacklist-tag-text">{tag}</span>
                                        <button
                                            className="blacklist-tag-delete"
                                            onClick={() => onRemoveTag(tag)}
                                            title="Remove tag"
                                        >
                                            <i className="fas fa-times"></i>
                                        </button>
                                    </li>
                                ))}
                            </ul>
                        )}

                        {/* Delete Blacklisted Media Button */}
                        {tagArray.length > 0 && (
                            <button 
                                className="blacklist-delete-all-btn"
                                onClick={onDeleteBlacklisted}
                                title="Delete all media containing blacklisted tags"
                            >
                                <i className="fas fa-trash-alt"></i> Delete All Blacklisted Media
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export const SettingsDialog = memo(SettingsDialogComponent);
SettingsDialog.displayName = 'SettingsDialog';

// ScraplistModal - standalone modal for managing scrapelist
const ScraplistModalComponent = ({
    showScrapelist,
    scrapelist,
    onClose,
    onRemoveScrapelist,
    onAddToScrapelist,
    autoScrapeEnabled,
    onAutoScrapeChange,
    autoScrapeModes = ['off', 'on', 'scrapelist'],
    autoScrapeTitles = { off: 'OFF', on: 'ON', scrapelist: 'SCRAPELIST' },
    availableDomains = ['Rule34', 'E621', 'Pixiv', 'RedGifs', 'SpankBang', 'SafeBooru'],
    onScrapeScrapelist,
    onImportScrapeList,
    onExportScrapeList
}) => {
    const [newScrapelitUrl, setNewScrapelitUrl] = useState('');
    const [scrapelistPage, setScrapelistPage] = useState(0);
    const [selectedDomains, setSelectedDomains] = useState(['All']);
    const [showDomainDropdown, setShowDomainDropdown] = useState(false);
    const itemsPerPage = 15;
    const modalRef = useRef(null);

    const handleDomainToggle = (domain) => {
        setSelectedDomains(prevDomains => {
            const newDomains = [...prevDomains];
            const index = newDomains.indexOf(domain);
            
            if (domain === 'All') {
                // Select all or deselect all
                return newDomains.includes('All') ? [] : ['All'];
            }
            
            // Remove 'All' if adding a specific domain
            const allIndex = newDomains.indexOf('All');
            if (allIndex > -1 && index === -1) {
                newDomains.splice(allIndex, 1);
            }
            
            // Toggle domain
            if (index > -1) {
                newDomains.splice(index, 1);
            } else {
                newDomains.push(domain);
            }
            
            // If no domains selected, default to 'All'
            return newDomains.length === 0 ? ['All'] : newDomains;
        });
    };

    const handleAddUrlInput = () => {
        const trimmedUrl = newScrapelitUrl.trim();
        if (!trimmedUrl) return;

        // If input is a URL (starts with http/https), use it as-is
        if (trimmedUrl.toLowerCase().startsWith('http')) {
            onAddToScrapelist(trimmedUrl);
            setNewScrapelitUrl('');
            setScrapelistPage(0);
            return;
        }

        // Otherwise, format as "domain1,domain2:tag1,tag2" if domains are selected
        let formattedUrl = trimmedUrl;
        if (selectedDomains.length > 0 && !selectedDomains.includes('All')) {
            // Check if already in correct format
            if (!trimmedUrl.includes(':')) {
                const domainString = selectedDomains.join(',');
                formattedUrl = `${domainString}:${trimmedUrl}`;
            }
        }

        onAddToScrapelist(formattedUrl);
        setNewScrapelitUrl('');
        setScrapelistPage(0);
    };

    useClickOutsideModal(showScrapelist, modalRef, onClose);

    if (!showScrapelist || !scrapelist) return null;

    const totalPages = Math.ceil(scrapelist.length / itemsPerPage);
    const displayedItems = scrapelist.slice(
        scrapelistPage * itemsPerPage,
        (scrapelistPage + 1) * itemsPerPage
    );

    return (
        <div className="scrapelist-modal-overlay">
            <div className="scrapelist-modal" ref={modalRef}>
                <div className="scrapelist-modal-header">
                    <h2>Autoscrape</h2>
                    <div className="scrapelist-mode-selector">
                        <label htmlFor="autoscrape-mode">Mode:</label>
                        <select
                            id="autoscrape-mode"
                            value={autoScrapeEnabled}
                            onChange={(e) => onAutoScrapeChange(e.target.value)}
                            className="autoscrape-mode-dropdown"
                        >
                            {autoScrapeModes.map(mode => (
                                <option key={mode} value={mode}>
                                    {autoScrapeTitles[mode]}
                                </option>
                            ))}
                        </select>
                    </div>
                    <button onClick={onClose} className="modal-close-btn" aria-label="Close">
                        <i className="fas fa-times"></i>
                    </button>
                </div>

                <div className="scrapelist-modal-content">
                    <h3 className="scrapelist-section-title">Scrapelist ({scrapelist.length} entries)</h3>
                    <div className="scrapelist-add-controls">
                        <div className="scrapelist-domain-filter-wrapper">
                            <button
                                className="scrapelist-domain-filter-button"
                                onClick={() => setShowDomainDropdown(!showDomainDropdown)}
                                title="Filter by domain"
                            >
                                <i className="fas fa-globe"></i>
                                <span>
                                    {selectedDomains.includes('All') ? 'All' : selectedDomains.length > 1 ? `${selectedDomains.length} selected` : selectedDomains[0] || 'All'}
                                </span>
                                <i className={`fas fa-chevron-down ${showDomainDropdown ? 'open' : ''}`}></i>
                            </button>
                            {showDomainDropdown && (
                                <div className="scrapelist-domain-filter-menu">
                                    <div
                                        className={`scrapelist-domain-filter-item ${selectedDomains.includes('All') ? 'active' : ''}`}
                                        onClick={() => handleDomainToggle('All')}
                                    >
                                        <span className="scrapelist-domain-checkbox"></span>
                                        All
                                    </div>
                                    {availableDomains.map(domain => (
                                        <div
                                            key={domain}
                                            className={`scrapelist-domain-filter-item ${selectedDomains.includes(domain) ? 'active' : ''}`}
                                            onClick={() => handleDomainToggle(domain)}
                                        >
                                            <span className="scrapelist-domain-checkbox"></span>
                                            {domain}
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                        <input
                            type="text"
                            value={newScrapelitUrl}
                            onChange={(e) => setNewScrapelitUrl(e.target.value)}
                            onKeyPress={(e) => e.key === 'Enter' && handleAddUrlInput()}
                            placeholder="Paste URL or domain tags..."
                            className="scrapelist-add-input"
                            autoFocus
                        />
                        <button
                            className="scrapelist-add-btn"
                            onClick={handleAddUrlInput}
                            title="Add URL to scrapelist"
                        >
                            <i className="fas fa-plus"></i> Add
                        </button>
                    </div>

                    <ul className="scrapelist-simple">
                        {displayedItems.map((url, idx) => (
                            <ScraplistItem
                                key={`${url}-${scrapelistPage * itemsPerPage + idx}`}
                                url={url}
                                index={scrapelistPage * itemsPerPage + idx}
                                onRemove={onRemoveScrapelist}
                            />
                        ))}
                    </ul>

                    {scrapelist.length > 0 && (
                        <button
                            className="scrapelist-scrape-btn"
                            onClick={onScrapeScrapelist}
                            title="Start scraping all entries in the scrapelist"
                        >
                            <i className="fas fa-play"></i> Scrape the Scrapelist
                        </button>
                    )}

                    <div className="scrapelist-file-controls">
                        <label className="scrapelist-file-btn scrapelist-import-btn">
                            <i className="fas fa-upload"></i> Import from File
                            <input
                                type="file"
                                accept=".json"
                                onChange={onImportScrapeList}
                                style={{ display: 'none' }}
                            />
                        </label>
                        {scrapelist.length > 0 && (
                            <button
                                className="scrapelist-file-btn scrapelist-export-btn"
                                onClick={onExportScrapeList}
                                title="Export scrapelist to file"
                            >
                                <i className="fas fa-download"></i> Export to File
                            </button>
                        )}
                    </div>

                    {totalPages > 1 && (
                        <div className="scrapelist-pagination">
                            <button
                                onClick={() => setScrapelistPage(p => Math.max(0, p - 1))}
                                disabled={scrapelistPage === 0}
                                className="pagination-btn"
                            >
                                ← Previous
                            </button>
                            <span className="pagination-info">
                                Page {scrapelistPage + 1} of {totalPages}
                            </span>
                            <button
                                onClick={() => setScrapelistPage(p => p + 1)}
                                disabled={(scrapelistPage + 1) * itemsPerPage >= scrapelist.length}
                                className="pagination-btn"
                            >
                                Next →
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export const ScraplistModal = memo(ScraplistModalComponent);
ScraplistModal.displayName = 'ScraplistModal';

// Add Link Modal Component
const AddLinkModalComponent = ({ isOpen, onClose, onAddLink }) => {
    const [linkUrl, setLinkUrl] = useState('');
    const [tagInput, setTagInput] = useState('');
    const modalRef = useRef(null);

    useClickOutsideModal(isOpen, modalRef, onClose);

    const handleSubmit = (e) => {
        e.preventDefault();
        
        if (!linkUrl.trim()) {
            alert('Please enter a link');
            return;
        }

        onAddLink({
            url: linkUrl.trim(),
            tag: tagInput.trim()
        });

        // Reset form
        setLinkUrl('');
        setTagInput('');
    };

    if (!isOpen) return null;

    return (
        <div className="add-link-modal-overlay">
            <div className="add-link-modal" ref={modalRef}>
                <div className="add-link-modal-header">
                    <h2>Add Link</h2>
                    <button 
                        className="add-link-close-btn"
                        onClick={onClose}
                        aria-label="Close modal"
                    >
                        <i className="fas fa-times"></i>
                    </button>
                </div>
                
                <form onSubmit={handleSubmit} className="add-link-form">
                    <div className="add-link-form-group">
                        <label htmlFor="linkUrl">Link URL:</label>
                        <input
                            id="linkUrl"
                            type="url"
                            placeholder="https://example.com"
                            value={linkUrl}
                            onChange={(e) => setLinkUrl(e.target.value)}
                            className="add-link-input"
                            autoFocus
                        />
                    </div>

                    <div className="add-link-form-group">
                        <label htmlFor="tagInput">Tag (optional):</label>
                        <input
                            id="tagInput"
                            type="text"
                            placeholder="e.g., scenery, original"
                            value={tagInput}
                            onChange={(e) => setTagInput(e.target.value)}
                            className="add-link-input"
                        />
                    </div>

                    <div className="add-link-form-actions">
                        <button 
                            type="button"
                            className="add-link-btn-cancel"
                            onClick={onClose}
                        >
                            Cancel
                        </button>
                        <button 
                            type="submit"
                            className="add-link-btn-submit"
                        >
                            <i className="fas fa-plus"></i>
                            Add Link
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export const AddLinkModal = memo(AddLinkModalComponent);
AddLinkModal.displayName = 'AddLinkModal';